written = []
for cid in IDS:
    assert cid in P, cid
    rec = {"case_id": cid, **P[cid]}
    assert set(rec) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert set(rec["trigger"]) == {"changed_main","reserve_used","disputed","reason"}, cid
    assert 0.0 <= rec["confidence"] <= 1.0
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    written.append(cid)

# readback verification
assert len(written) == len(IDS) == 20
for cid in IDS:
    back = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert back["case_id"] == cid, cid
    assert all(back.get(k) for k in ("prediction_text","basis")) or back["basis"], cid
    assert set(back) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print(f"OK written={len(written)} changed_main={cm} reserve_used={ru} disputed={di}")
